function isBalanced(root) {
  function dfs(node) {
    if (node === null) return -1;
    const leftHeight = dfs(node.left);
    if (leftHeight === -1) return -1;
    const rightHeight = dfs(node.right);
    if (rightHeight === -1) return -1;
    if (Math.abs(leftHeight - rightHeight) > 1) return -1;
    return 1 + Math.max(leftHeight, rightHeight);
  }
  return dfs(root) !== -1;
}

// balanced: 1 over (2 over 4) and 3
const balanced = new Node(1, new Node(2, new Node(4)), new Node(3));
// skewed chain 1 -> 2 -> 3 -> 4 (left only)
const skewed = new Node(1, new Node(2, new Node(3, new Node(4))));

console.log('balanced:', isBalanced(balanced));
console.log('skewed:', isBalanced(skewed));

