class Node { constructor(v, l = null, r = null) { this.value = v; this.left = l; this.right = r; } }

// BROKEN: returns one number, recomputes children, no skip-state
function rob(node) {
  if (node === null) return 0;
  const withNode = node.value + rob(node.left) + rob(node.right);
  const withoutNode = rob(node.left) + rob(node.right);
  return Math.max(withNode, withoutNode);
}

//        3
//       / \
//      2   3
//       \   \
//        3   1   -> best = 3 + 3 + 1 = 7
const tree = new Node(3, new Node(2, null, new Node(3)), new Node(3, null, new Node(1)));
console.log('best:', rob(tree));
